const D = { temp: .5, scale: 1, energy: .6, speed: 1, density: .5, hue: 250, x: .5, y: .5, style: 'duotone-walls', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse spin grid: scale -> cell size (bigger scale = chunkier domains / coarser lattice) ----
const CW = Math.max(60, Math.min(200, Math.round(170 / Math.max(0.4, P.scale))));
const CH = Math.max(40, Math.min(200, Math.round(CW * height / Math.max(1, width))));
const NC = CW * CH;
const seedI = P.seed | 0;

// deterministic uniform hash for the initial random spin field (no p5 random -> no global pollution)
const gh = (i, s) => { let h = (i * 374761393 + s * 668265263 + seedI * 2654435761) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); h ^= h >>> 16; return (h >>> 0) / 4294967296; };

// ---- (re)build lattice on size / seed change ----
const buildSig = CW + 'x' + CH + '_' + seedI;
if (S.buildSig !== buildSig || !S.sp) {
  S.buildSig = buildSig;
  S.sp = new Int8Array(NC);
  for (let k = 0; k < NC; k++) S.sp[k] = gh(k, 7777) < 0.5 ? -1 : 1;
  S.rng = ((seedI * 2654435761) ^ 0x9e3779b9) >>> 0; if (S.rng === 0) S.rng = 0x1234567;
  S.done = null;
}

// ---- temperature: drift slowly through the critical point Tc~2.269 on K.section (order -> filigree -> noise) ----
const Tc = 2.269;
const drift = Math.sin(K.t * 0.05 + K.section * 0.35) * 0.85; // continuous slow sweep through Tc (morph over ~60-120s)
let T = Tc + (P.temp - 0.5) * 2.6 + drift + (K.intensity - 0.5) * 0.5;
T = Math.max(0.6, Math.min(4.2, T));
const p4 = Math.exp(-4 / T), p8 = Math.exp(-8 / T); // Boltzmann accept probs for the only positive dE values

// ---- Metropolis sweeps, gated on continuous K.t (never re-phases; pauses only if the clock pauses) ----
const rate = NC * (0.7 + P.speed * 1.5 + K.intensity * 1.0);
const target = Math.floor(K.t * rate);
if (S.done == null || target < S.done) S.done = target;
let need = target - S.done;
if (need > NC * 3) need = NC * 3;
let r = S.rng >>> 0;
const sp = S.sp;
for (let a = 0; a < need; a++) {
  r ^= r << 13; r ^= r >>> 17; r ^= r << 5; r >>>= 0;
  const i = (r % CW);
  r ^= r << 13; r ^= r >>> 17; r ^= r << 5; r >>>= 0;
  const j = (r % CH);
  const rj = j * CW, idx = rj + i;
  const s = sp[idx];
  const l = sp[rj + (i ? i - 1 : CW - 1)];
  const rr = sp[rj + (i + 1 < CW ? i + 1 : 0)];
  const u = sp[(j ? j - 1 : CH - 1) * CW + i];
  const d = sp[(j + 1 < CH ? j + 1 : 0) * CW + i];
  const dE = 2 * s * (l + rr + u + d); // -8..8
  if (dE <= 0) sp[idx] = -s;
  else {
    r ^= r << 13; r ^= r >>> 17; r ^= r << 5; r >>>= 0;
    const rnd = r / 4294967296;
    if (dE === 4) { if (rnd < p4) sp[idx] = -s; }
    else { if (rnd < p8) sp[idx] = -s; }
  }
}
S.rng = r >>> 0;
S.done = target;

// ---- coarse render buffer ----
if (!S.g || S.gw !== CW || S.gh !== CH) { S.g = createGraphics(CW, CH); S.g.pixelDensity(1); S.gw = CW; S.gh = CH; }

// ---- HSV -> rgb 0..255 into a shared triple (no per-pixel allocation) ----
const OUT = [0, 0, 0];
function setHSV(o, h, s, v) {
  h = ((h % 360) + 360) % 360; const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let rr, gg, bb;
  if (h < 60) { rr = c; gg = x; bb = 0; } else if (h < 120) { rr = x; gg = c; bb = 0; } else if (h < 180) { rr = 0; gg = c; bb = x; }
  else if (h < 240) { rr = 0; gg = x; bb = c; } else if (h < 300) { rr = x; gg = 0; bb = c; } else { rr = c; gg = 0; bb = x; }
  o[0] = (rr + m) * 255; o[1] = (gg + m) * 255; o[2] = (bb + m) * 255;
}

const eexp = Math.min(1.35, 0.52 + P.energy * 0.72 + K.intensity * 0.22 + A.rms * 0.45);
const hb = P.hue + K.section * 6 + Math.sin(K.t * 0.04) * 10; // slow palette drift for dramaturgy
const goldH = hb + 155;
const wallV = Math.min(0.9, (0.46 + P.density * 0.34) * eexp + 0.05);
const style = P.style;
const mode = style === 'thermal' ? 1 : style === 'monochrome' ? 2 : style === 'neon' ? 3 : style === 'copper' ? 4 : 0;

// ---- paint every cell (sim advances each frame, so redraw each frame; ~16k px = cheap) ----
{
  const g = S.g; g.loadPixels(); const px = g.pixels;
  for (let j = 0; j < CH; j++) {
    const jp = (j + 1 < CH ? j + 1 : 0), rj = j * CW, rjp = jp * CW;
    const jm = (j ? j - 1 : CH - 1) * CW;
    for (let i = 0; i < CW; i++) {
      const ip = (i + 1 < CW ? i + 1 : 0), im = (i ? i - 1 : CW - 1);
      const idx = rj + i, s = sp[idx];
      const sR = sp[rj + ip], sD = sp[rjp + i];
      const wall = (sR !== s) || (sD !== s);
      if (mode === 1) { // thermal: false-color heat by local disorder (ordered interior cool, writhing walls hot)
        const dis = (sp[rj + im] !== s) + (sR !== s) + (sp[jm + i] !== s) + (sD !== s);
        const heat = dis * 0.25;
        setHSV(OUT, 260 - heat * 255, 0.92 - heat * 0.5, Math.min(1, (0.12 + heat * heat * 0.55 + heat * 0.35) * eexp));
      } else if (mode === 2) { // monochrome: black/white spins, white domain walls
        const v = wall ? 1 : (s > 0 ? 0.82 : 0.16);
        setHSV(OUT, 0, 0, Math.min(1, v * (0.85 + P.energy * 0.3)));
      } else if (mode === 3) { // neon: domain walls only, glowing on near-black (abstract contour of the boundaries)
        if (wall) setHSV(OUT, (hb + (s > 0 ? 0 : 45) + K.t * 8) % 360, 0.85, Math.min(1, 0.95 * eexp));
        else { OUT[0] = 3; OUT[1] = 3; OUT[2] = 9; }
      } else if (mode === 4) { // copper: verdigris vs copper-orange patina, dark oxidized seams
        if (wall) setHSV(OUT, 32, 0.55, Math.min(1, 0.16 * eexp));
        else if (s > 0) setHSV(OUT, 26, 0.72, Math.min(1, 0.52 * eexp));
        else setHSV(OUT, 152, 0.42, Math.min(1, 0.44 * eexp));
      } else { // duotone-walls (default): indigo down-spin, gold up-spin, glowing domain walls
        if (wall) setHSV(OUT, hb + 88, 0.16, wallV);
        else if (s > 0) setHSV(OUT, goldH, 0.82, Math.min(1, 0.52 * eexp));
        else setHSV(OUT, hb, 0.70, Math.min(1, 0.40 * eexp));
      }
      const o = 4 * idx; px[o] = OUT[0]; px[o + 1] = OUT[1]; px[o + 2] = OUT[2]; px[o + 3] = 255;
    }
  }
  g.updatePixels();
}

// ---- draw: bilinear upscale (walls bloom softly) with slow continuous rotation + zoom breath = motion floor ----
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
translate(width / 2 + (P.x - 0.5) * width * 0.16, height / 2 + (P.y - 0.5) * height * 0.16);
rotate(K.t * 0.012 + K.section * 0.02);
const zoom = 1.62 + Math.sin(K.t * 0.09) * 0.06 + A.rms * 0.12;
imageMode(CENTER);
image(S.g, 0, 0, width * zoom, height * zoom);
imageMode(CORNER);
pop();

// ---- audio glow ON TOP of the clk baseline (all-zero during validation; partial alpha, never strobes) ----
if (A.bass > 0.01 || A.treble > 0.01 || A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  fill((hb + 155) % 360, 45, 100, (A.bass * 0.6 + A.rms * 0.4) * P.energy * 16);
  rect(0, 0, width, height);
  fill((hb + 200) % 360, 30, 100, A.treble * P.energy * 12);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
